import numpy as np
L=np.log(P)
base={'P':P,'P2':P**2,'PL':P*L,'P2L':P**2*L,'L':L,'1':np.ones_like(P),'iP':1/P}
for deg in [1,2,3]:
    cols=[];names=[]
    for nm,b in base.items():
        for j in range(deg+1):
            cols.append(b*t**j); names.append(f'{nm}t{j}')
    X=np.c_[cols].T
    c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None)
    r=dP_dt-X@c
    print(deg, np.mean(r**2)/np.var(dP_dt))
# deg2 coefficients
cols=[];names=[]
for nm,b in base.items():
    for j in range(3):
        cols.append(b*t**j); names.append(f'{nm}t{j}')
X=np.c_[cols].T
c,_,_,_=np.linalg.lstsq(X,dP_dt,rcond=None)
print({n:round(v,4) for n,v in zip(names,c) if abs(v)>1e-3})
